package main

import (
	"archive/zip"
	"os"
	"path/filepath"
	"testing"
)

func writeZip(t *testing.T, path string, entries map[string]string) {
	t.Helper()
	f, err := os.Create(path)
	if err != nil {
		t.Fatalf("create zip: %v", err)
	}
	defer f.Close()
	zw := zip.NewWriter(f)
	for name, content := range entries {
		w, err := zw.Create(name)
		if err != nil {
			t.Fatalf("create entry %s: %v", name, err)
		}
		if _, err := w.Write([]byte(content)); err != nil {
			t.Fatalf("write entry %s: %v", name, err)
		}
	}
	if err := zw.Close(); err != nil {
		t.Fatalf("close zip: %v", err)
	}
}

func TestExtractsLegitimateEntries(t *testing.T) {
	dir := t.TempDir()
	zipPath := filepath.Join(dir, "good.zip")
	destDir := filepath.Join(dir, "dest")
	writeZip(t, zipPath, map[string]string{
		"readme.txt":     "hello",
		"sub/nested.txt": "nested content",
	})

	if err := Extract(zipPath, destDir); err != nil {
		t.Fatalf("Extract failed on a legitimate archive: %v", err)
	}
	got, err := os.ReadFile(filepath.Join(destDir, "readme.txt"))
	if err != nil || string(got) != "hello" {
		t.Fatalf("readme.txt not extracted correctly: %v %q", err, got)
	}
	got2, err := os.ReadFile(filepath.Join(destDir, "sub", "nested.txt"))
	if err != nil || string(got2) != "nested content" {
		t.Fatalf("sub/nested.txt not extracted correctly: %v %q", err, got2)
	}
}

func TestRejectsZipSlipEntry(t *testing.T) {
	dir := t.TempDir()
	zipPath := filepath.Join(dir, "evil.zip")
	destDir := filepath.Join(dir, "dest")
	// Does NOT start with ".." but still escapes destDir after Join+Clean -
	// a naive strings.HasPrefix(name, "..") check would miss this.
	evilName := "sub/../../pwned-outside.txt"
	writeZip(t, zipPath, map[string]string{evilName: "pwned"})

	err := Extract(zipPath, destDir)
	if err == nil {
		t.Fatalf("expected Extract to reject a path-escaping entry, got nil error")
	}

	outside := filepath.Join(dir, "pwned-outside.txt")
	if _, statErr := os.Stat(outside); statErr == nil {
		t.Fatalf("zip slip: a file was written outside destDir at %s", outside)
	}
}

